{
  "name": "BeltTransfer",
  "description": "Pick from one belt and place on another: one state per move of the clamp carriage, four boxes.",
  "version": "1.0.0",
  "variables": {
    "local": [
      {
        "name": "Active",
        "type": "BOOL",
        "initialValue": false,
        "comment": "The transfer was started"
      },
      {
        "name": "State",
        "type": "INT",
        "initialValue": 0,
        "comment": "One state per move: 0 idle, 2 wait for a box, 3 lower, 4 close, 5 lift, 6 carry, 7 lower, 8 open and settle, 9 lift, 10 return, 11 finished"
      },
      {
        "name": "Settle",
        "type": "TON",
        "comment": "A box must stand still at the blade before the clamp comes down"
      },
      {
        "name": "Rest",
        "type": "TON",
        "comment": "A put-down box must lie still before the outfeed runs again"
      },
      {
        "name": "Lifts",
        "type": "CTU",
        "comment": "Counts the lifts at the blade: the first three bring the next box"
      },
      {
        "name": "Placed",
        "type": "CTU",
        "comment": "Counts the boxes put down"
      },
      {
        "name": "Delivered",
        "type": "CTU",
        "comment": "Counts the boxes that passed EyeOut"
      }
    ],
    "inputs": [
      {
        "name": "Start",
        "type": "BOOL",
        "address": "%I0.0",
        "comment": "StartButton.pressed: start the transfer"
      },
      {
        "name": "Waiting",
        "type": "BOOL",
        "address": "%I0.1",
        "comment": "EyePick.detect: a box waits at the stop blade of the infeed"
      },
      {
        "name": "OutEye",
        "type": "BOOL",
        "address": "%I0.2",
        "comment": "EyeOut.detect: a box passes on the outfeed belt"
