      {
        "name": "XMax",
        "type": "BOOL",
        "address": "%I0.4",
        "comment": "Pick1.xAtMax: the carriage is over the outfeed"
      },
      {
        "name": "YMin",
        "type": "BOOL",
        "address": "%I0.5",
        "comment": "Pick1.yAtMin: the clamp is down"
      },
      {
        "name": "YMax",
        "type": "BOOL",
        "address": "%I0.6",
        "comment": "Pick1.yAtMax: the clamp is up"
      },
      {
        "name": "Gripped",
        "type": "BOOL",
        "address": "%I0.7",
        "comment": "Pick1.gripped: the clamp holds a box"
